#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {1, 2, 3};
    for (int x : v) x += 10;
    for (int &y : v) y += 100;
    for (int z : v) cout << z << " ";
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int i = 5;
    int count = 0;
    do {
        count++;
        i++;
    } while (i < 3);
    cout << count << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int hits = 0;
    for (int i = 0; i < 5; i++) {
        for (int j = i + 1; j < 5; j++) {
            hits++;
        }
    }
    cout << hits << endl;
    return 0;
}
